-- Tabela Clientes CREATE TABLE Clientes (     ID INTEGER PRIMARY KEY AUTOINCREMENT,     nomeCliente VARCHAR(100) NOT NULL,     emailCliente VARCHAR(100) NOT NULL );  -- Tabela Compras CREATE TABLE Compras (     CompraID INTEGER PRIMARY KEY AUTOINCREMENT,     ClienteID INTEGER NOT NULL,     NomeLivro VARCHAR(150) NOT NULL,     FOREIGN KEY (ClienteID) REFERENCES Clientes(ID) );  -- Inserindo dados de exemplo (opcional) INSERT INTO Clientes (nomeCliente, emailCliente) VALUES  ('João Silva', 'joao@email.com'), ('Maria Santos', 'maria@email.com'), ('Pedro Costa', 'pedro@email.com');  INSERT INTO Compras (ClienteID, NomeLivro) VALUES  (1, 'O Cortiço'), (1, 'Dom Casmurro'), (2, '1984'), (3, 'O Hobbit');
